<template>
  <div class="mcsa-result">
    <p v-if="data.found === false" class="empty-note">{{ sourceText(data.message) || 'No matching M-CSA record was found.' }}</p>
    <template v-else>
      <section class="mcsa-identity" aria-label="M-CSA record overview">
        <div class="identity-top"><a v-if="entryUrl" :href="entryUrl" target="_blank" rel="noopener noreferrer">M-CSA {{ basic.mcsa_id }} ↗</a><span class="tag">Curated mechanism record</span></div>
        <h4>{{ basic.enzyme_name || 'M-CSA enzyme record' }}</h4>
        <div class="identity-links"><span v-if="accession">Reference protein <a :href="`https://www.uniprot.org/uniprotkb/${accession}/entry`" target="_blank" rel="noopener noreferrer">{{ accession }} ↗</a></span><span v-for="ec in ecCodes" :key="ec">EC {{ ec }}</span></div>
        <div class="record-stats"><div><strong>{{ referenceSites.length }}</strong><span>Reference residue annotations</span></div><div><strong>{{ mechanisms.length }}</strong><span>Mechanism proposals</span></div><div><strong>{{ pdbIds.length }}</strong><span>PDB references</span></div><div v-if="sequence"><strong>{{ sequence.length }}<small> aa</small></strong><span>Reference sequence</span></div></div>
        <p v-if="description" class="source-prose">{{ description }}</p>
        <p class="note">Annotations describe the M-CSA reference record. Missing fields are not evidence of absence; related proteins may use different residue numbering.</p>
        <details v-if="ecCodes.length" class="fold"><summary>Explore EC classification</summary><EcClassification :payload="basic" /></details>
      </section>

      <section class="mcsa-section" aria-label="M-CSA reaction">
        <div class="section-heading"><div><span class="eyebrow">REACTION</span><h4>From substrates to products</h4></div><span v-if="data.reaction?.is_polymeric" class="tag">Polymeric reaction</span></div>
        <div v-if="reactants.length || products.length" class="reaction-layout">
          <div v-for="side in [{label:'Reactants',compounds:reactants},{label:'Products',compounds:products}]" :key="side.label" class="reaction-side"><h5>{{ side.label }}</h5><div class="compound-grid"><article v-for="(compound,i) in side.compounds" :key="i" class="compound-card"><div class="compound-heading"><span v-if="compound.count != null && compound.count !== 1" class="coefficient">{{ compound.count }} ×</span><strong>{{ sourceText(compound.name) || 'Unnamed compound' }}</strong></div><a v-if="chebiUrl(compound.chebi_id)" :href="chebiUrl(compound.chebi_id)" target="_blank" rel="noopener noreferrer">ChEBI {{ compound.chebi_id }} ↗</a><ChemicalPreview v-if="compound.smiles" :smiles="compound.smiles" :title="`M-CSA ${side.label.toLowerCase()} · ${compound.name}`" /><p v-else class="note">No molecular structure was included.</p><details v-if="compound.smiles" class="literal"><summary>SMILES</summary><code>{{ compound.smiles }}</code></details></article></div><p v-if="!side.compounds.length" class="empty-note">No {{ side.label.toLowerCase() }} were included.</p></div>
          <div class="reaction-arrow" aria-hidden="true">→</div>
        </div>
        <p v-else class="empty-note">No reaction compounds were included in this record.</p>
      </section>

      <section class="mcsa-section" aria-label="M-CSA mechanism explorer">
        <div class="section-heading"><div><span class="eyebrow">MECHANISM EXPLORER</span><h4>Follow the catalytic steps</h4></div><span class="tag">M-CSA source descriptions</span></div>
        <template v-if="mechanisms.length">
          <div class="mechanism-choices" role="group" aria-label="Mechanism proposals"><button v-for="(item,i) in mechanisms" :key="item.key" :aria-pressed="mechanismIndex === i" @click="mechanismIndex=i">Proposal {{ item.mechanism_id ?? i+1 }}<small v-if="item.rating != null">M-CSA rating {{ item.rating }}</small></button></div>
          <p v-if="mechanisms.length>1" class="note">Read each proposal and its evidence separately. The source may include historical or disputed mechanisms; ratings are M-CSA annotations, not model probabilities.</p>
          <div class="mechanism-summary"><p v-if="mechanism.summary_text" class="source-prose">{{ sourceText(mechanism.summary_text) }}</p><p v-else class="note">No summary was included for this proposal.</p><div v-if="components.length" class="role-tags"><span v-for="component in components" :key="component">{{ component }}</span></div></div>
          <template v-if="steps.length">
            <nav class="step-nav" aria-label="Mechanism steps"><button v-for="(step,i) in steps" :key="step.key" :aria-pressed="stepIndex===i" @click="stepIndex=i"><span>{{ step.step_id }}</span>{{ step.is_product ? 'Products' : `Step ${step.step_id}` }}</button></nav>
            <article class="mechanism-step" aria-live="polite"><div class="step-heading"><h5>{{ activeStep.is_product ? 'Products' : `Step ${activeStep.step_id}` }}</h5><span>{{ stepIndex+1 }} / {{ steps.length }} recorded stages</span></div><p class="source-prose">{{ sourceText(activeStep.description) || 'No step description was included.' }}</p><MechanismFigure :key="`${mechanism.key}-${activeStep.key}`" :url="mcsaFigureUrl(activeStep.figure)" :title="`M-CSA ${basic.mcsa_id} · proposal ${mechanism.mechanism_id ?? mechanismIndex+1} · ${activeStep.is_product ? 'products' : `step ${activeStep.step_id}`}`" /><div class="step-controls"><button :disabled="stepIndex===0" @click="stepIndex--">← Previous</button><button :disabled="stepIndex===steps.length-1" @click="stepIndex++">Next →</button></div></article>
            <details class="fold"><summary>All step descriptions <span>{{ steps.length }} stages</span></summary><ol class="step-list"><li v-for="step in steps" :key="step.key"><strong>{{ step.is_product ? 'Products' : `Step ${step.step_id}` }}</strong><p>{{ sourceText(step.description) }}</p></li></ol></details>
          </template>
          <p v-else class="empty-note">No individual steps were included for this proposal.</p>
          <details class="fold literature" :open="references.length>0"><summary>Evidence &amp; literature for this proposal <span>{{ references.length }} references</span></summary><ol v-if="references.length" class="reference-list"><li v-for="(reference,i) in references" :key="i"><p>{{ sourceText(reference.title) || 'Reference title not provided' }}</p><div class="reference-links"><a v-if="/^\d+$/.test(reference.pubmed_id)" :href="`https://pubmed.ncbi.nlm.nih.gov/${reference.pubmed_id}/`" target="_blank" rel="noopener noreferrer">PMID {{ reference.pubmed_id }} ↗</a><a v-if="doiUrl(reference.doi)" :href="doiUrl(reference.doi)" target="_blank" rel="noopener noreferrer">DOI ↗</a></div><div v-if="reference.evidence_types?.length" class="role-tags"><span v-for="evidence in reference.evidence_types" :key="evidence">{{ sourceText(evidence) }}</span></div></li></ol><p v-else class="empty-note">No literature references were saved with this proposal. <a v-if="entryUrl" :href="entryUrl" target="_blank" rel="noopener noreferrer">Read the M-CSA entry ↗</a></p></details>
        </template>
        <p v-else class="empty-note">No mechanism description was included. Other annotations remain available below.</p>
      </section>

      <section class="mcsa-section" aria-label="M-CSA catalytic residues">
        <div class="section-heading"><div><span class="eyebrow">CATALYTIC RESIDUES</span><h4>Residues and their recorded roles</h4></div><button v-if="sites.length || pdbSites.length" @click="exportSites">Download residues CSV</button></div>
        <p class="numbering-note">UniProt positions and PDB author numbers are shown separately. Step descriptions and diagrams retain their original labels; no numbering offset is inferred.</p>
        <div class="site-controls"><div class="view-choices" role="group" aria-label="Residue numbering"><button :aria-pressed="siteView==='uniprot'" @click="siteView='uniprot'">UniProt</button><button :aria-pressed="siteView==='pdb'" @click="siteView='pdb'">PDB</button></div><label v-if="siteView==='uniprot' && accessionOptions.length>1">Protein <select v-model="siteAccession"><option v-for="id in accessionOptions" :key="id" :value="id">{{ id }}{{ id===accession ? ' · reference' : '' }}</option></select></label><label v-if="siteView==='pdb' && pdbIds.length>1">Structure <select v-model="sitePdb"><option value="">All PDB entries</option><option v-for="id in pdbIds" :key="id" :value="id">{{ id.toUpperCase() }}</option></select></label></div>
        <ResultPreview v-if="visibleSites.length" :title="`M-CSA ${basic.mcsa_id} · ${siteView==='pdb' ? 'PDB' : 'UniProt'} residues`"><div class="residue-table"><table><thead><tr><th>{{ siteView==='pdb' ? 'PDB / chain' : 'Protein' }}</th><th>Residue</th><th v-if="siteView==='pdb'">Author number</th><th>Role &amp; annotation</th></tr></thead><tbody><tr v-for="(site,i) in visibleSites" :key="site.key || i" :class="{'selected-residue':siteView==='uniprot' && site.position && site.position===selectedPosition}"><td><a v-if="siteView==='pdb' && pdbUrl(site.pdb_id)" :href="pdbUrl(site.pdb_id)" target="_blank" rel="noopener noreferrer">{{ site.pdb_id.toUpperCase() }} ↗</a><span v-else>{{ site.uniprot_id }}</span><small v-if="siteView==='pdb'">Chain {{ site.chain || 'not specified' }}</small><small>{{ site.is_reference ? 'Reference' : 'Related record' }}</small></td><td><button v-if="siteView==='uniprot' && site.position" :aria-label="`Locate ${site.code}${site.resid}`" @click="selectPosition(site.position)">{{ site.code }}{{ site.resid }}</button><span v-else>{{ site.code }}{{ site.resid }}</span></td><td v-if="siteView==='pdb'">{{ site.auth_resid ?? 'Not provided' }}</td><td><p v-if="site.main_annotation">{{ sourceText(site.main_annotation) }}</p><div v-if="site.roles?.length" class="role-tags"><span v-for="role in site.roles" :key="role">{{ sourceText(role) }}</span></div><p v-else class="note">{{ sourceText(site.roles_summary) || 'No specific role terms were included.' }}</p></td></tr></tbody></table></div></ResultPreview>
        <p v-else class="empty-note">No residue annotations were included for this view.</p>
        <details v-if="roleMatrix.roles.length" class="fold"><summary>Compare roles across reference residues</summary><p class="note">Filled cells indicate an explicit role annotation; empty cells mean no role was listed.</p><ResultPreview title="M-CSA reference residue role matrix"><div class="role-matrix"><table><thead><tr><th>Role</th><th v-for="row in roleMatrix.rows" :key="row.key">{{ row.label }}</th></tr></thead><tbody><tr v-for="role in roleMatrix.roles" :key="role"><th>{{ role }}</th><td v-for="row in roleMatrix.rows" :key="row.key" :class="{present:row.roles.includes(role)}"><span :aria-label="row.roles.includes(role) ? 'Annotated' : 'Not listed'">{{ row.roles.includes(role) ? '●' : '—' }}</span></td></tr></tbody></table></div></ResultPreview></details>
      </section>

      <ReferenceStructure v-if="accession" ref="structure" :accession="accession" :sequence="sequence" :sites="referenceSites" :site-palette="sitePalette" annotation-source="M-CSA" @select="selectFromStructure" />
      <section v-if="sequence" class="mcsa-section" aria-label="M-CSA reference sequence"><div class="section-heading"><div><span class="eyebrow">REFERENCE SEQUENCE</span><h4>{{ accession }} · {{ sequence.length }} residues</h4></div><button @click="exportFasta">Download FASTA</button></div><div class="site-pills"><button v-for="site in referenceSites.filter(s=>s.position)" :key="site.key" :aria-pressed="selectedPosition===site.position" @click="selectPosition(site.position)">{{ site.code }}{{ site.resid }}</button></div><details class="fold" open><summary>Numbered sequence <span>M-CSA saved reference</span></summary><SequencePreview :sequence="sequence" :annotations="sequenceMarks" :selected-position="selectedPosition" interactive @select="selectPosition" /></details><p v-if="selectionNote" class="note" role="status">{{ selectionNote }}</p><p v-if="referenceSites.some(site=>!site.position)" class="numbering-note">Some residue annotations do not match the saved sequence at their reported positions. They remain in the table and are excluded from structure mapping.</p></section>
      <p v-else class="empty-note">No matching reference sequence was saved in this result. Residue annotations remain available, but sequence-to-structure mapping is disabled.</p>

      <details class="fold cofactor-section" :open="cofactors.length>0"><summary>Cofactors <span>{{ cofactors.length ? `${cofactors.length} entries` : 'Not included' }}</span></summary><div v-if="cofactors.length" class="cofactor-grid"><article v-for="(cofactor,i) in cofactors" :key="i" class="compound-card"><div class="compound-heading"><span class="tag">{{ cofactor.pdb_code }}</span><strong>{{ sourceText(cofactor.name) || cofactor.pdb_code }}</strong></div><a v-if="chebiUrl(cofactor.chebi_id)" :href="chebiUrl(cofactor.chebi_id)" target="_blank" rel="noopener noreferrer">ChEBI {{ cofactor.chebi_id }} ↗</a><div class="role-tags"><span v-for="(role,j) in cofactor.roles || []" :key="j">{{ sourceText(role.role) }}</span></div><ChemicalPreview v-if="cofactor.smiles" :smiles="cofactor.smiles" :title="`M-CSA cofactor · ${cofactor.name || cofactor.pdb_code}`" /><details v-if="cofactor.smiles" class="literal"><summary>SMILES</summary><code>{{ cofactor.smiles }}</code></details></article></div><p v-else class="note">No cofactors were included; this does not establish cofactor independence.</p></details>
      <p class="attribution">Source: <a v-if="entryUrl" :href="entryUrl" target="_blank" rel="noopener noreferrer">Mechanism and Catalytic Site Atlas (M-CSA) ↗</a><span v-else>Mechanism and Catalytic Site Atlas (M-CSA)</span>. Text and diagrams: <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. The AlphaFold model is a separate predicted reference.</p>
    </template>
  </div>
</template>

<script setup>
import {computed,ref,watch} from 'vue';
import {accessionId} from '@/utils/enzymeInfo';
import {ecNumbers} from '@/utils/ecHierarchy';
import {sourceText,mcsaEntryUrl,mcsaFigureUrl,chebiUrl,doiUrl,pdbUrl,mechanismList,referenceSequence,uniprotSites,rolesMatrix} from '@/utils/mcsa';
import {downloadData} from '@/utils/workspace';
import ChemicalPreview from './ChemicalPreview.vue';
import MechanismFigure from './MechanismFigure.vue';
import ReferenceStructure from './ReferenceStructure.vue';
import SequencePreview from './SequencePreview.vue';
import ResultPreview from './ResultPreview.vue';
import EcClassification from './EcClassification.vue';
const props=defineProps({data:{type:Object,required:true}});
const basic=computed(()=>props.data.basic_info || {}),accession=computed(()=>accessionId(basic.value.reference_uniprot_id)),entryUrl=computed(()=>mcsaEntryUrl(basic.value.mcsa_id)),description=computed(()=>sourceText(basic.value.description)),ecCodes=computed(()=>ecNumbers(basic.value));
const reactants=computed(()=>props.data.reaction?.reactants || []),products=computed(()=>props.data.reaction?.products || []),cofactors=computed(()=>props.data.cofactors || []);
const mechanisms=computed(()=>mechanismList(props.data)),mechanismIndex=ref(0),stepIndex=ref(0);
const mechanism=computed(()=>mechanisms.value[mechanismIndex.value] || {}),steps=computed(()=>mechanism.value.steps || []),activeStep=computed(()=>steps.value[stepIndex.value] || {}),references=computed(()=>mechanism.value.references || []),components=computed(()=>[...new Set(sourceText(mechanism.value.components_summary).split(',').map(s=>s.trim()).filter(Boolean))]);
watch(mechanismIndex,()=>{stepIndex.value=0;});
const sequence=computed(()=>referenceSequence(props.data)),sites=computed(()=>uniprotSites(props.data)),referenceSites=computed(()=>sites.value.filter(s=>s.uniprot_id===accession.value)),roleMatrix=computed(()=>rolesMatrix(referenceSites.value));
const sitePalette={'M-CSA residue':'#148760'},sequenceMarks=computed(()=>referenceSites.value.filter(s=>s.position).map(s=>({...s,color:'#148760'})));
const pdbSites=computed(()=>props.data.active_sites_pdb || []),pdbIds=computed(()=>[...new Set(pdbSites.value.map(s=>s.pdb_id).filter(id=>pdbUrl(id)))]),accessionOptions=computed(()=>[...new Set(sites.value.map(s=>s.uniprot_id).filter(Boolean))]);
const siteView=ref('uniprot'),siteAccession=ref(''),sitePdb=ref(''),selectedPosition=ref(null),selectionNote=ref(''),structure=ref(null);
const visibleSites=computed(()=>siteView.value==='uniprot' ? sites.value.filter(s=>s.uniprot_id===siteAccession.value) : pdbSites.value.filter(s=>!sitePdb.value || s.pdb_id===sitePdb.value));
watch(()=>props.data,()=>{mechanismIndex.value=0;stepIndex.value=0;siteAccession.value=accessionOptions.value.includes(accession.value)?accession.value:accessionOptions.value[0] || '';sitePdb.value='';selectedPosition.value=null;selectionNote.value='';},{immediate:true});
function selectPosition(position){selectedPosition.value=position;const located=structure.value?.focusPosition(position);selectionNote.value=`Selected ${sequence.value[position-1]}${position}. ${located ? 'Located in the matching reference structure.' : 'No validated coordinate is currently available; load the reference structure to inspect matching coordinates.'}`;}
function selectFromStructure(position){selectedPosition.value=position;selectionNote.value=`Selected ${sequence.value[position-1]}${position} in the reference structure and sequence.`;}
function exportFasta(){downloadData(`>${accession.value} M-CSA ${basic.value.mcsa_id}\n${sequence.value.match(/.{1,60}/g).join('\n')}\n`,`${accession.value}-mcsa.fasta`,'text/plain');}
function exportSites(){const q=value=>`"${String(value ?? '').replaceAll('"','""')}"`;const rows=[['numbering','protein_or_structure','chain','residue','position','author_position','roles','annotation'],...sites.value.map(s=>['UniProt',s.uniprot_id,'',s.code,s.resid,'',s.roles.join('; '),sourceText(s.main_annotation)]),...pdbSites.value.map(s=>['PDB',s.pdb_id,s.chain,s.code,s.resid,s.auth_resid,(s.roles || []).join('; '),sourceText(s.main_annotation)])];downloadData(rows.map(r=>r.map(q).join(',')).join('\n'),`mcsa-${basic.value.mcsa_id}-residues.csv`,'text/csv');}
</script>

